window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-979b1e5e9f4c9e53"]={"versions": [{"id": "FIG-979b1e5e9f4c9e53", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Tabelle zur Spezifikation von XML-Persistenzregeln im AUTOSAR-Metamodell (AUTOSAR Model Persistence Rules for XML). Das Diagramm stellt die Zuordnung von Modelleigenschaften bzw. Referenzen ohne Aggregation (<code>aggregation=none</code>) zu XML-Schema-Konstrukten (<code>xsd:choice</code>, <code>xsd:group</code>) sowie die resultierende Serialisierung in einer XML-Instanz dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>XML-Schema-Komponenten:\n<ul class=\"fig-list\"><li><code>&lt;xsd:choice&gt;</code> mit Kardinalität <code>minOccurs=&quot;0&quot;</code>, <code>maxOccurs=&quot;unbounded&quot;</code> zur Gruppierung der referenzierten Gruppen <code>&lt;xsd:group ref=&quot;AR:B1&quot;/&gt;</code> und <code>&lt;xsd:group ref=&quot;AR:B2&quot;/&gt;</code>.\n</li><li><code>&lt;xsd:choice&gt;</code> mit Kardinalität <code>minOccurs=&quot;0&quot;</code>, <code>maxOccurs=&quot;1&quot;</code> für die referenzierte Gruppe <code>&lt;xsd:group ref=&quot;AR:C&quot;/&gt;</code>.\n</li></ul>\n</li><li>XML-Instanzelemente:\n<ul class=\"fig-list\"><li>Hüll-/Wurzelelement <code>&lt;...&gt;</code> bzw. <code>&lt;/...&gt;</code>.\n</li><li>Direkte Kindelemente <code>&lt;ATT-B1&gt;</code>, <code>&lt;ATT-B2&gt;</code> und <code>&lt;ATT-C&gt;</code> mit zugehörigen Textwerten (<code>someValueB1</code>, <code>someValueB2</code>, <code>someValueC</code>).\n</li></ul>\n</li><li>Schnittstelle / Namensraum: Zielnamensraum-Präfix <code>AR:</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm veranschaulicht ein statisches Mapping-Muster:</p>\n<ol class=\"fig-list\"><li>Eine unvollständige oder mehrfache Aggregation/Referenz auf Typen B1 und B2 wird im XML-Schema über eine Choice-Struktur mit unbeschränkter Obergrenze abgebildet.\n</li><li>Eine optionale Referenz auf Typ C wird als Choice-Struktur mit Multiplizität 0..1 definiert.\n</li><li>Bei der XML-Instanziierung werden die atomaren Eigenschaften (<code>ATT-B1</code>, <code>ATT-B2</code>, <code>ATT-C</code>) der aufgelösten Gruppen ohne zusätzliche Property-Wrapper direkt im umgebenden Element serialisiert.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliche Syntaxdefinition für Serialisierer und Deserialisierer im AUTOSAR-Tooling. Wenn kein Wrapper-Element deklariert ist, sind die Attribute bzw. Gruppeninhalte unmittelbar in den Sequenz-/Auswahlfluss des umschließenden Modellelements einzubetten. Die Multiplizitätsattribute <code>minOccurs</code> und <code>maxOccurs</code> des XSD-Schemas steuern die Validierung der Instanzdaten.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-abf09cc63c924d4d", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Tabelle zur Spezifikation von XML-Persistenzregeln im AUTOSAR-Metamodell (AUTOSAR Model Persistence Rules for XML). Das Diagramm stellt die Zuordnung von Modelleigenschaften bzw. Referenzen ohne Aggregation (<code>aggregation=none</code>) zu XML-Schema-Konstrukten (<code>xsd:choice</code>, <code>xsd:group</code>) sowie die resultierende Serialisierung in einer XML-Instanz dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>XML-Schema-Komponenten:\n<ul class=\"fig-list\"><li><code>&lt;xsd:choice&gt;</code> mit Kardinalität <code>minOccurs=&quot;0&quot;</code>, <code>maxOccurs=&quot;unbounded&quot;</code> zur Gruppierung der referenzierten Gruppen <code>&lt;xsd:group ref=&quot;AR:B1&quot;/&gt;</code> und <code>&lt;xsd:group ref=&quot;AR:B2&quot;/&gt;</code>.\n</li><li><code>&lt;xsd:choice&gt;</code> mit Kardinalität <code>minOccurs=&quot;0&quot;</code>, <code>maxOccurs=&quot;1&quot;</code> für die referenzierte Gruppe <code>&lt;xsd:group ref=&quot;AR:C&quot;/&gt;</code>.\n</li></ul>\n</li><li>XML-Instanzelemente:\n<ul class=\"fig-list\"><li>Hüll-/Wurzelelement <code>&lt;...&gt;</code> bzw. <code>&lt;/...&gt;</code>.\n</li><li>Direkte Kindelemente <code>&lt;ATT-B1&gt;</code>, <code>&lt;ATT-B2&gt;</code> und <code>&lt;ATT-C&gt;</code> mit zugehörigen Textwerten (<code>someValueB1</code>, <code>someValueB2</code>, <code>someValueC</code>).\n</li></ul>\n</li><li>Schnittstelle / Namensraum: Zielnamensraum-Präfix <code>AR:</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm veranschaulicht ein statisches Mapping-Muster:</p>\n<ol class=\"fig-list\"><li>Eine unvollständige oder mehrfache Aggregation/Referenz auf Typen B1 und B2 wird im XML-Schema über eine Choice-Struktur mit unbeschränkter Obergrenze abgebildet.\n</li><li>Eine optionale Referenz auf Typ C wird als Choice-Struktur mit Multiplizität 0..1 definiert.\n</li><li>Bei der XML-Instanziierung werden die atomaren Eigenschaften (<code>ATT-B1</code>, <code>ATT-B2</code>, <code>ATT-C</code>) der aufgelösten Gruppen ohne zusätzliche Property-Wrapper direkt im umgebenden Element serialisiert.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliche Syntaxdefinition für Serialisierer und Deserialisierer im AUTOSAR-Tooling. Wenn kein Wrapper-Element deklariert ist, sind die Attribute bzw. Gruppeninhalte unmittelbar in den Sequenz-/Auswahlfluss des umschließenden Modellelements einzubetten. Die Multiplizitätsattribute <code>minOccurs</code> und <code>maxOccurs</code> des XSD-Schemas steuern die Validierung der Instanzdaten.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-17b0316b66874975", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Tabellarische Spezifikationsmatrix für Modell-Persistenzregeln im AUTOSAR-Metamodell gemäß Anforderung <code>5.4.11 [APRXML0016] Create composite property representation (0000) [Tc0010Sc0000]</code> und Übergang zu <code>5.5 Create reference representation [Tc0012]</code>. Die Darstellung definiert Templates und Bedingungen für Eigenschaften, bei denen weder Rollen- noch Typ-Wrapper generiert werden.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Bedingungen und Metamodell-Eigenschaften:\n<ul class=\"fig-list\"><li><code>Property</code>\n</li><li>Tagged-Value-Bedingung: <code>xml.roleWrapperElement == false &amp;&amp; xml.roleElement == false &amp;&amp; xml.typeWrapperElement == false &amp;&amp; xml.typeElement == false</code>.\n</li></ul>\n</li><li>Schema-Template:\n<ul class=\"fig-list\"><li><code>&lt;xsd:choice minOccurs=&quot;&lt;%=lowerMultiplicity%&gt;&quot; maxOccurs=&quot;&lt;%=upperMultiplicity%&gt;&quot;&gt;</code>\n</li><li>Iterator <code>&lt;% for all types { %&gt;</code> mit Gruppenreferenz <code>&lt;xsd:group ref=&quot;&lt;%=typeXmlNsPrefix%&gt;:&lt;%=typeXmlName%&gt;&quot;/&gt;</code>.\n</li><li>Konkrete Ausprägung: <code>&lt;xsd:choice minOccurs=&quot;0&quot; maxOccurs=&quot;unbounded&quot;&gt;</code> für <code>AR:B1</code> / <code>AR:B2</code> sowie <code>&lt;xsd:choice minOccurs=&quot;0&quot; maxOccurs=&quot;1&quot;&gt;</code> für <code>AR:C</code>.\n</li></ul>\n</li><li>XML-Instanzstrukturen:\n<ul class=\"fig-list\"><li>Gekapselte Serialisierung mit Elementen <code>&lt;B1&gt;</code>, <code>&lt;B2&gt;</code>, <code>&lt;C&gt;</code> und Kindelementen <code>&lt;ATT-B1&gt;</code>, <code>&lt;ATT-B2&gt;</code>, <code>&lt;ATT-C&gt;</code>.\n</li><li>Ungekapselte Serialisierung („See above“) mit direkter Einbettung von <code>&lt;ATT-B1&gt;</code>, <code>&lt;ATT-B2&gt;</code>, <code>&lt;ATT-C&gt;</code> im Wurzelelement <code>&lt;...&gt;</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Regelbasierte Transformationsabfolge:</p>\n<ol class=\"fig-list\"><li>Prüfung der Metadaten-Bedingung: Alle Flags für Rollen- und Typ-Elemente bzw. -Wrapper müssen auf <code>false</code> evaluiert sein.\n</li><li>Schema-Generierung: Dynamische Erzeugung von <code>&lt;xsd:choice&gt;</code> basierend auf <code>&lt;%=lowerMultiplicity%&gt;</code> und <code>&lt;%=upperMultiplicity%&gt;</code> sowie Iteration über alle Subtypen zur Einbettung von <code>&lt;xsd:group&gt;</code>.\n</li><li>XML-Generierung: Gemäß der Spezifikation wird kein eigenes XML-Element für das Property erzeugt; das Inhaltsmodell des Typs und aller Subtypen wird direkt in die <code>xsd:group</code> der besitzenden Klasse eingebettet. Instanzbeispiele verdeutlichen den Unterschied zwischen getaggten/umhüllten Typen und flacher Einbettung.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindende Spezifikationsregel <code>[APRXML0016]</code> inklusive Testfallzuordnung <code>[Tc0010Sc0000]</code>. Generatorwerkzeuge müssen die logische UND-Verknüpfung der vier Tagged Values validieren, um zu entscheiden, ob kein XML-Element erzeugt und das Inhaltsmodell direkt in die besitzende <code>xsd:group</code> überführt wird. Instanzen ohne Wrapper müssen dem gezeigten Muster direkt eingebetteter Kindelemente entsprechen.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-979b1e5e9f4c9e53", "to": "FIG-abf09cc63c924d4d", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-abf09cc63c924d4d", "to": "FIG-17b0316b66874975", "fr": "R3.1.5", "tr": "R3.2.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Kontext- und Spezifikationsrahmen: Ergänzung der Spezifikationsanforderung <code>5.4.11 [APRXML0016] Create composite property representation (0000) [Tc0010Sc0000]</code> sowie der nachfolgenden Überschrift <code>5.5 Create reference representation [Tc0012]</code>.\n</li><li>Bedingungslogik: Hinzufügung der Auswertebedingungen <code>Property</code> und <code>xml.roleWrapperElement == false &amp;&amp; xml.roleElement == false &amp;&amp; xml.typeWrapperElement == false &amp;&amp; xml.typeElement == false</code>.\n</li><li>Schema-Generierungsregel: Aufnahme eines parametrierten Templates <code>&lt;xsd:choice minOccurs=&quot;&lt;%=lowerMultiplicity%&gt;&quot; maxOccurs=&quot;&lt;%=upperMultiplicity%&gt;&quot;&gt;</code> mit Schleife <code>&lt;% for all types { %&gt; &lt;xsd:group ref=&quot;&lt;%=typeXmlNsPrefix%&gt;:&lt;%=typeXmlName%&gt;&quot;/&gt; &lt;% } // end for all types %&gt; &lt;/xsd:choice&gt;</code>.\n</li><li>Begleitende Mapping-Regel: Hinzufügung der normativen Festlegung, dass kein XML-Element für das Property generiert wird und das Inhaltsmodell direkt in die <code>xsd:group</code> der besitzenden Klasse eingebettet wird (<code>See above</code>).\n</li><li>XML-Instanzbeispiele: Ergänzung eines vorangestellten Beispiels mit Element-Wrapping (<code>&lt;B1&gt;</code>, <code>&lt;B2&gt;</code>, <code>&lt;C&gt;</code>) vor dem bisherigen unwrapped Beispiel.\n</li></ul>"}]};
